    func moveSelectedTask(offset: Int) {
        guard let task = selectedTask,
              !task.isChore,
              let projectID = task.projectID,
              var tasks = tasksByProjectID[projectID]?.sorted(by: taskSort),
              let currentIndex = tasks.firstIndex(where: { $0.id == task.id })
        else {
            return
        }

        let destination = currentIndex + offset
        guard tasks.indices.contains(destination) else { return }

        tasks.swapAt(currentIndex, destination)
        engine.sendReorderProjectTasks(projectId: projectID, taskIds: tasks.map(\.id))
    }

    /// Apply an explicit column choice from the work-card popover's "Move"
    /// buttons. The drag path does not come through here — it reports its
    /// drop target and the engine resolves it
    /// (`sendMoveWorkItemOnBoard`). Two extra concerns vs. a pure status
    /// edit, both per `tools/boss/docs/designs/work-kanban.md`:
    ///
    /// - Choosing Doing (target status `active`) also fires
    ///   `RequestExecution` so the engine schedules a worker. The
    ///   engine is idempotent — a non-terminal execution already
    ///   running for this work item won't get a duplicate.
    /// - Move OUT of Doing while a live worker is attached is
    ///   blocked — except for two intentional gestures:
    ///   (a) Choosing Backlog (`todo`): engine stops the worker,
    ///       releases the lease, and parks the card — no autostart.
    ///   (b) Terminal transitions (`done`, `archived`): these mirror the
    ///       engine's own lifecycle resolutions and are always allowed.
    func moveTask(_ taskID: String, to column: WorkBoardColumnKey) {
        guard let task = task(withID: taskID) else { return }
        let targetStatus = column.targetStatus
        guard task.status != targetStatus else { return }

        if task.status == "active"
            && !Self.terminalKanbanStatuses.contains(targetStatus)
            && column != .backlog  // backlog drag = stop+park: engine handles teardown
            && hasLiveWorker(forTaskID: taskID)
        {
            appendSystemMessage(
                "\(task.name) is being worked on by a live worker. Stop the worker before moving the card out of Doing.",
                alwaysShow: true
            )
            return
        }

        // Optimistic update: move the card to the destination column immediately
        // before the RPC completes. The engine remains the authority — on failure
        // we bounce back via bounceBackOptimisticMoves.
        let originColumn = effectiveBoardColumn(for: task)
        pendingMoveOriginByTaskID[taskID] = originColumn
        optimisticColumnByTaskID[taskID] = column
        invalidateWorkCache()

        engine.sendUpdateWorkItem(id: task.id, patch: ["status": targetStatus])

        if targetStatus == "active" {
            engine.sendRequestExecution(workItemId: task.id)
        }
    }

    /// Statuses that the engine itself can drive a chore into at run
    /// completion. The kanban must allow the human to mirror those
    /// transitions even from `active` so a successful PR-merge flow
    /// can move a card to Done without first stopping the worker.
    private static let terminalKanbanStatuses: Set<String> = [
        "done",
        "archived",
    ]

    /// True iff the work item has a non-terminal worker currently
    /// attached (running, paused on input, or idle between turns). Shared
    /// with the kanban drop path (`attemptDrop`), which applies the same
    /// out-of-Doing rule as the popover's explicit Move buttons.
    /// `WorkerActivity.terminated` and `.errored` count as "no live
    /// worker" — the slot is no longer holding the run open.
    func hasLiveWorker(forTaskID taskID: String) -> Bool {
        guard let live = workerLiveState(forTaskID: taskID) else {
            return false
        }
        switch live.activity {
        case .terminated, .errored:
            return false
        case .spawning, .working, .waitingForInput, .idle:
            return true
        }
    }

    func toggleBlocked(for taskID: String) {
        guard let task = task(withID: taskID) else { return }
        let nextStatus: String
        switch task.status {
        case "blocked":
            nextStatus = "active"
        case "active":
            nextStatus = "blocked"
        default:
            return
        }
        engine.sendUpdateWorkItem(id: task.id, patch: ["status": nextStatus])
    }

    /// Update a task or chore's priority via the inline picker on the
    /// detail popover. No-ops when the new value matches the current
    /// one so an idle picker tap doesn't generate write traffic.
    func setPriority(for taskID: String, to priority: WorkPriority) {
        guard let task = task(withID: taskID) else { return }
        guard task.priority != priority.rawValue else { return }
        engine.sendUpdateWorkItem(id: task.id, patch: ["priority": priority.rawValue])
    }

    func startIfNeeded() {
        guard !didStart else { return }

        // Swap-on-startup fallback (design doc §4): if a staged update is ready and
        // the user is in automatic mode, replace the bundle *before* the engine
        // launches (so the new engine binary is what gets spawned), then hand off to
        // the detached relaunch helper and exit — it relaunches us into the new
        // version. If no swap applies, this returns false and we continue normally.
        // Placed here because this is the single chokepoint guaranteed to run before
        // `processController.start()`. See [[UpdateLifecycle]].
        if UpdateLifecycle.applyStartupSwapIfNeeded() {
            exit(0)
        }

        didStart = true

        // UI tests drive explicit fixture clients and events directly. The
        // `commonInit` fallback schedules this method automatically, so do not
        // start either a real process or a reconnecting client from XCTest.
        // Controller startup has dedicated injected tests.
        guard !BossEnginePaths.isRunningInTestContext else { return }

        let autostart = ProcessInfo.processInfo.environment["BOSS_ENGINE_AUTOSTART"] != "0"
        if autostart {
            let processController = self.processController
            DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                do {
                    try processController.start()
                    DispatchQueue.main.async {
                        self?.startEngineIfNeeded()
                    }
                } catch {
                    DispatchQueue.main.async {
                        self?.appendSystemMessage(
                            "Failed to launch engine: \(error.localizedDescription)",
                            alwaysShow: true
                        )
                    }
                }
            }
        } else {
            startEngineIfNeeded()
        }
    }

    /// `true` while a user-initiated engine restart is running. The
    /// unreachable banner binds its "Restart engine" button to the
    /// inverse so a second click can't queue another terminate +
    /// relaunch on top of the first one (issue #697).
    @Published private(set) var isRestartingEngine = false
    /// App-managed engine recovery state. This is distinct from the socket
    /// connection state: the latter says whether a listener is reachable,
    /// while this says whether the app is actively replacing a dead listener
    /// or has exhausted its bounded retry policy.
    @Published private(set) var engineSupervisionState: EngineSupervisionState = .running

    /// User-initiated recovery from the unreachable banner. Discovers the
    /// reachable engine by socket (token-auth shutdown RPC first, then a
    /// validated peer/pid-file SIGTERM/SIGKILL fallback) and
    /// relaunches it. The `EngineClient` reconnect loop picks the new
    /// socket up automatically once it accepts.
    ///
    /// Routes the terminate+launch through the same background queue
    /// `startIfNeeded()` uses so the main thread never blocks on
    /// `terminateEngine`'s up-to-5s SIGKILL wait. `isRestartingEngine`
    /// drives the banner button's `.disabled` state.
    func restartEngine() {
        guard !isRestartingEngine else { return }
        isRestartingEngine = true

        let processController = self.processController
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            var restartError: Error?
            do {
                try processController.restart()
            } catch {
                restartError = error
            }
            DispatchQueue.main.async {
                guard let self else { return }
                self.isRestartingEngine = false
                if let restartError {
                    self.appendSystemMessage(
                        "Failed to restart engine: \(restartError.localizedDescription)",
                        alwaysShow: true
                    )
                }
                // Make sure the EngineClient is started even if the
                // very first `startIfNeeded()` failed before launching
                // it (autostart=0 paths also flow through here).
                self.startEngineIfNeeded()
            }
        }
    }

    func refreshWork() {
        guard isConnected else { return }
        engine.sendListProducts()
        if let productID = currentSelectedProductID {
            engine.sendGetWorkTree(productId: productID, flow: .manualRefresh)
        }
    }

    /// Ask the engine to resolve the design-doc pointer for every
    /// project whose row carries a non-nil `designDocPath`. Projects
    /// with no pointer set are skipped so the engine doesn't burn an
    /// RPC just to be told `not_set` — the affordance is hidden in
    /// that case anyway. Re-issued on every `WorkTree` so a re-point
    /// landed in another session flows through to the icon.
    func refreshDesignDocStates(for projects: [WorkProject]) {
        guard isConnected else { return }
        let pending = projects.filter { $0.designDocPath != nil }
        guard !pending.isEmpty else { return }
        currentDesignDocResolveBatch = DesignDocResolveBatch(
            startDate: Date(),
            pendingProjectIDs: Set(pending.map(\.id)),
            initialCount: pending.count
        )
        for project in pending {
            engine.sendResolveProjectDesignDoc(projectID: project.id)
        }
    }

    /// Open the design-doc pointer for `project`. Dispatch follows
    /// `ProjectDesignDocState`:
    ///
    /// - `.notSet` — affordance shouldn't have been clickable. No-op.
    /// - `.broken` — surface the engine's reason as a work error so
    ///   the user can re-point. The re-point sheet is tracked
    ///   separately (design Q5).
    /// - `.resolved` — dispatch priority:
    ///   1. `rawContentURL` present: route through the engine via
    ///      [[openDesignDocViaEngine]] (serves cache, revalidates in
    ///      background) and open in the async markdown viewer. This is
    ///      correct for both merged (main) and in-review (PR branch) docs —
    ///      the GitHub ref is the authoritative source regardless of cube
    ///      workspace state. A leased workspace may be on a different task's
    ///      branch even when `resolved.branch == "main"`, so reading from
    ///      disk is not safe.
    ///   2. `rawContentURL` absent (non-GitHub repo or older engine) AND a
    ///      workspace is leased for the resolved repo AND branch is `main`:
    ///      render via [[designRendererOpener]] (in-app renderer) when wired,
    ///      otherwise hand the `file://` URL to [[urlOpener]].
    ///   3. Fall through to [[urlOpener]] with the web URL.
    func openProjectDesignDoc(_ project: WorkProject) {
        let shortID = project.shortID.map { "\($0)" } ?? project.id
        let state = designDocStateByProjectID[project.id] ?? .notSet
        switch state {
        case .notSet:
            return
        case .broken(let reason):
            workErrorMessage = "Design doc pointer is broken: \(reason)"
        case .resolved(let resolved, let workspacePath, let webURL, let rawContentURL):
            // Prefer fetching via rawContentURL (GitHub API). This is correct
            // regardless of cube workspace state — the workspace may be on a
            // different branch even when resolved.branch == "main".
            if rawContentURL != nil {
                let projectName = project.name
                let clickStart = Date()
                designDocTimingLog.info("phase=dispatch project=\(shortID, privacy: .public) path=engine")
                if let opener = asyncMarkdownViewerOpener {
                    // Open the window immediately, then resolve through
                    // the engine (cache + revalidate). App-side `gh api`
                    // is no longer on this path.
                    asyncMarkdownViewerVM.state = .loading
                    asyncMarkdownViewerVM.clickStartTime = clickStart
                    let openWindowStart = Date()
                    opener()
                    let openWindowMs = Int(Date().timeIntervalSince(openWindowStart) * 1000)
                    designDocTimingLog.info("phase=open_window project=\(shortID, privacy: .public) duration_ms=\(openWindowMs, privacy: .public)")
                    openDesignDocViaEngine(
                        ref: DesignDocRef(
                            repoRemoteURL: resolved.repoRemoteURL,
                            path: resolved.path,
                            gitRef: resolved.branch
                        ),
                        title: projectName,
                        artifact: resolved.commentArtifact,
                        projectShortID: shortID
                    )
                } else {
                    // Headless / test path: no in-app viewer wired.
                    openDesignDocFallback(webURL: webURL)
                }
                return
            }
            // rawContentURL absent (non-GitHub repo or older engine): fall back
            // to the workspace fast-path for merged docs when a workspace is
            // available. Only safe for branch == "main" designs where we can
            // reasonably assume the workspace holds the merged file.
            if let workspacePath, isWorkspaceFastPathEligible(kind: resolved.kind),
               resolved.branch == "main" {
                designDocTimingLog.info("phase=dispatch project=\(shortID, privacy: .public) path=workspace")
                if let opener = designRendererOpener,
                   let content = DesignRendererContent.from(
                       projectID: project.id,
                       projectName: project.name,
                       resolved: resolved,
                       workspacePath: workspacePath,
                       webURL: webURL
                   ) {
                    opener(content)
                    return
                }
                let absolute = (workspacePath as NSString)
                    .appendingPathComponent(resolved.path)
                urlOpener(URL(fileURLWithPath: absolute))
                return
            }
            guard let url = URL(string: webURL) else {
                workErrorMessage = "Design doc URL could not be parsed: \(webURL)"
                return
            }
            designDocTimingLog.info("phase=dispatch project=\(shortID, privacy: .public) path=webURL")
            urlOpener(url)
        }
    }

    /// Open a local `.md`/`.markdown` file in the in-app design renderer,
    /// reusing [[designRendererOpener]] — the same window and rendering
    /// path as [[openProjectDesignDoc]] and File ▸ Open (⌘O). This is the
    /// shared entry point for every "open a markdown file" surface: the
    /// File ▸ Open panel, `open -a Boss foo.md` from the shell, and
    /// Finder's "Open With ▸ Boss" (both routed through the app's
    /// `application(_:open:)` delegate callback, which calls this after
    /// [[designRendererOpener]] is wired).
    ///
    /// `allowOSFallback` controls what happens when the renderer isn't
    /// wired: the File ▸ Open panel path (the default, `true`) falls
    /// back to `urlOpener` (the OS-registered handler) — safe there
    /// because the user explicitly picked the file from within Boss, not
    /// because the OS handed it to Boss. The OS open-document path
    /// (`AppDelegate.application(_:open:)`) passes `false`: an event
    /// that arrived *from* LaunchServices must never be handed back to
    /// `NSWorkspace.shared.open`, since Boss can itself be the
    /// OS-registered `.md` handler after this change — falling back
    /// would re-dispatch the file to Boss's own open-document handler
    /// (or silently bounce it to a different app). When the fallback is
    /// disallowed and the renderer isn't wired, the open is dropped with
    /// a log line rather than silently lost.
    func openLocalMarkdownFile(url: URL, allowOSFallback: Bool = true) {
        let content = DesignRendererContent.forLocalFile(path: url.path)
        if let opener = designRendererOpener {
            opener(content)
        } else if allowOSFallback {
            urlOpener(url)
        } else {
            markdownOpenLog.warning(
                "Dropped OS-delivered markdown open for \(url.path, privacy: .public) — design renderer not wired yet"
            )
        }
    }

    /// Headless / test fallback for the doc-fetch dispatch in
    /// [[openProjectDesignDoc]] / [[openTaskDoc]], taken only when
    /// [[asyncMarkdownViewerOpener]] isn't wired (no `ContentView` in-graph
    /// to own the singleton viewer window) — production always wires it.
    /// Hands the doc straight to `urlOpener` rather than fetching content
    /// there's no viewer to show it in.
    @MainActor
    func openDesignDocFallback(webURL: String) {
        if let url = URL(string: webURL) {
            urlOpener(url)
        } else {
            workErrorMessage = "Design doc URL could not be parsed: \(webURL)"
        }
    }

    /// Loads `task.description` — already in memory, no fetch — into the
    /// singleton design-doc viewer and opens it. Used by "Read full
    /// description" (see [[WorkCardPopoverView]]) so that affordance shares
    /// the same `Window` scene, and therefore the same NSWindow behaviour
    /// under a fullscreen main window, as the design-doc icon path.
    ///
    /// `pendingRenderProjectShortID` is left `nil` so
    /// [[MarkdownDocumentChrome]]'s design-doc `phase=parse` /
    /// `phase=interactive` timing — gated on a non-empty `projectShortID` —
    /// never fires for a task-description open; that instrumentation is
    /// scoped to the design-doc click-to-first-paint journey.
    @MainActor
    func openTaskDescription(_ task: WorkTask) {
        asyncMarkdownViewerVM.pendingRenderProjectShortID = nil
        asyncMarkdownViewerVM.renderStartTime = nil
        asyncMarkdownViewerVM.clickStartTime = nil
        asyncMarkdownViewerVM.renderContentID = UUID()
        // Engine-minted revision briefs (`kind == "revision"`) always carry
        // the standing "HARD RULE: no punting" boilerplate ahead of their
        // findings (`render_revision_instructions` in
        // `tools/boss/engine/pr-review/src/render.rs`) — collapse it by
        // default so the findings are immediately visible. This is purely
        // presentational: the heading text matched here never changes what
        // `task.description` itself contains, which is what the worker
        // actually reads (see that Rust function's doc comment for the
        // cross-language contract this string must stay in sync with).
        asyncMarkdownViewerVM.collapsedByDefaultHeadings =
            task.kind == "revision" ? [RevisionBriefCollapsibleHeadings.hardRule] : []
        asyncMarkdownViewerVM.state = .loaded(
            title: task.name,
            markdown: task.description,
            artifact: .workItem(id: task.id)
        )
        asyncMarkdownViewerOpener?()
    }

    /// Apply a resolve response and close out the in-flight batch's timing
    /// summary once its last project reports. Stray responses for projects
    /// outside the current batch (a refresh that landed mid-flight) still
    /// update state — they just don't drive timing. Called from the
    /// `.projectDesignDocResolved` arm in [[ChatViewModel+EventHandling.swift]].
    func applyResolvedProjectDesignDoc(_ output: ResolveProjectDesignDocOutput) {
        if var batch = currentDesignDocResolveBatch,
           batch.pendingProjectIDs.remove(output.projectID) != nil {
            if batch.pendingProjectIDs.isEmpty {
                let ms = Int(Date().timeIntervalSince(batch.startDate) * 1000)
                designDocTimingLog.info("phase=resolve project=batch count=\(batch.initialCount, privacy: .public) duration_ms=\(ms, privacy: .public)")
                currentDesignDocResolveBatch = nil
            } else {
                currentDesignDocResolveBatch = batch
            }
        }
        designDocStateByProjectID[output.projectID] = output.state
    }

    /// Kanban open-affordance fast-path predicate: a `ResolvedDesignDocKind`
    /// is editor-eligible exactly when the doc lives in a repo Boss
    /// tracks as a Product (same- or other-product). External pointers
    /// always fall through to the web URL because cube can't lease
    /// untracked repos.
    private func isWorkspaceFastPathEligible(kind: ResolvedDesignDocKind) -> Bool {
        switch kind {
        case .sameProduct, .otherProduct:
            return true
        case .external:
            return false
        }
    }

    // MARK: - Pane bridge

    /// Handlers ContentView installs so the engine can drive libghostty panes
    /// through this model. The `engine_request` arms that call them live in
    /// [[ChatViewModel+EventHandling.swift]]; a build without GhosttyKit
    /// leaves them `nil` and those arms answer with a failure.
    var paneSpawnHandler: ((EngineSpawnRequest) -> EngineSpawnResult)?
    var paneReleaseHandler: ((Int, UInt32) -> EngineReleaseResult)?
    var paneAttachHandler: ((EngineAttachRequest) -> EngineAttachResult)?
    var coordinatorPaneAttachHandler: ((EngineCoordinatorAttachRequest) -> EngineCoordinatorAttachResult)?
    var paneDetachHandler: ((Int) -> EngineReleaseResult)?
    var paneSendHandler: ((Int, String, String) -> EngineSendResult)?
    var paneFocusHandler: ((Int) -> EngineFocusResult)?
    var paneInterruptHandler: ((Int) -> EngineInterruptResult)?
    /// Enumerates every slot the app currently hosts a session in,
    /// regardless of whether the engine has a live-tracked run for it.
    /// Backs `bossctl agents list --all`. `nil` build (Bazel without
    /// GhosttyKit) replies with an empty list — there is no pane
    /// allocator to enumerate.
    var paneListHostedHandler: (() -> [EngineHostedPaneEntry])?
    /// Invoked when the engine pushes `engine_pool_config`: forwards pool sizes to
    /// `WorkersWorkspaceModel` and records the engine's desired coordinator model.
    /// Parameters: workerSlots, automationSlots, reviewSlots, coordinatorModel.
    var panePoolConfigHandler: ((Int, Int, Int, String) -> Void)?

    /// The model the engine would use for the next coordinator creation.
    /// Paired with `attachedCoordinatorModel` to make a replacement explicitly
    /// destructive instead of silently restarting a live conversation.
    var requestedCoordinatorModel: String?
    var attachedCoordinatorModel: String?
    var attachedCoordinatorSpawnToken: String?
    var declinedCoordinatorRecreateToken: String?
    @Published var coordinatorModelRecreateConfirmation: CoordinatorModelRecreateConfirmation?

    /// The installed `claude` version, set only while the engine reports it
    /// as newer than what the running coordinator session actually launched
    /// with. Drives `CoordinatorUpdateBanner`; `nil` renders nothing. Clears
    /// itself the moment a reset makes the versions match again — there is
    /// no separate dismiss, since a wrong "up to date" reading is worse than
    /// the banner persisting until the operator acts.
    @Published var coordinatorUpdateAvailable: String?

    /// Whether the engine has confirmed this client is the registered app session.
    /// Reset on disconnect (see [[ChatViewModel+EventHandling.swift]]); set when
    /// `appSessionRegistered` is received.
    var isAppSessionRegistered = false
    // MARK: - Lookups and shared helpers

    var currentSelectedProductID: String? {
        selectedWorkProductID
    }

    private var taskCreationProject: WorkProject? {
        if let selectedProject {
            return selectedProject
        }
        if let selectedTask, let projectID = selectedTask.projectID {
            return project(withID: projectID)
        }
        return nil
    }

    func workTopic(forProductID productID: String) -> String {
        "work.product.\(productID)"
    }

    private var desiredWorkTopics: Set<String> {
        // `github.auth` is a global (per-host, not per-product) topic
        // carrying GitHub OAuth auth-state pushes; the engine fans every
        // device-flow transition out on it. We stay subscribed for the
        // whole session so the "GitHub account" settings subsection
        // re-renders live (OAuth device-flow design §4, TOPIC_GITHUB_AUTH).
        // `engine.health` carries health-state changes (dispatch pause/resume,
        // etc.) so the banner updates live without polling or restarting.
        var topics: Set<String> = ["work.products", "worker.live_states", "github.auth", "engine.health"]
        if let productID = currentSelectedProductID {
            topics.insert(workTopic(forProductID: productID))
        }
        return topics
    }

    /// Records a successful (re)connect. Exists so `hasConnectedOnce` can stay
    /// `private(set)` — `private` is file-scoped in Swift, and the `.connected`
    /// arm that flips it lives in [[ChatViewModel+EventHandling.swift]].
    func markConnected() {
        isConnected = true
        hasConnectedOnce = true
    }

    func refreshWorkSubscriptions() {
        guard isConnected else { return }
        let desired = desiredWorkTopics
        let toSubscribe = desired.subtracting(subscribedWorkTopics)
        let toUnsubscribe = subscribedWorkTopics.subtracting(desired)

        if !toUnsubscribe.isEmpty {
            engine.sendUnsubscribe(topics: Array(toUnsubscribe).sorted())
        }
        if !toSubscribe.isEmpty {
            engine.sendSubscribe(topics: Array(toSubscribe).sorted())
        }

        subscribedWorkTopics = desired
    }

    private func startEngineIfNeeded() {
        guard !didStartEngine else { return }
        didStartEngine = true
        engine.start()
    }


    func appendSystemMessage(_ text: String, alwaysShow: Bool = false) {
        guard alwaysShow || showSystemMessages else { return }
        // `write(contentsOf:)`, not the exception-raising `write(_:)` — see
        // [[DiagnosticWrite]]. A closed/broken stderr must never abort the app.
        try? FileHandle.standardError.write(contentsOf: Data("\(text)\n".utf8))
    }

    /// Non-private: [[ChatViewModel+BoardHelpers.swift]] resolves a task's
    /// owning product across several repo/badge helpers.
    func product(withID id: String) -> WorkProduct? {
        products.first { $0.id == id }
    }

    /// Lookup a project row by id across every product the model has
    /// loaded. Non-private so view code (the kanban project-card
    /// affordance) can resolve a section's `projectID` to a full
    /// `WorkProject` without re-walking the projects map itself.
    func project(withID id: String) -> WorkProject? {
        for projects in projectsByProductID.values {
            if let project = projects.first(where: { $0.id == id }) {
                return project
            }
        }
        return nil
    }

    func task(withID id: String) -> WorkTask? {
        if taskIndexByID == nil { rebuildTaskIndex() }
        return taskIndexByID?[id]
    }

    /// Look up any task or chore by id. Used by the kanban to resolve
    /// the parent task for revision card chrome.
    func workTask(withID id: String) -> WorkTask? {
        task(withID: id)
    }

    /// Cached output of `visibleWorkItems`. Filled lazily on read; reset to
    /// `nil` whenever a published input changes (see `invalidateWorkCache`).
    /// Keeps engine pushes that don't touch the work tree (e.g.
    /// `worker.live_states`) from re-walking the projects/tasks/chores trees.
    private var cachedVisibleItems: [WorkTask]?
    var cachedItemsByColumn: [WorkBoardColumnKey: [WorkTask]] = [:]
    var cachedSectionsByColumn: [WorkBoardColumnKey: [WorkBoardSection]] = [:]
    private var cachedAmbiguousRepoNames: Set<String>?
    /// O(1) id → work-item index over every task/chore/revision bucket.
    /// Built lazily on first lookup after any change (see `rebuildTaskIndex`);
    /// replaces a linear scan of all four buckets per `task(withID:)` call.
    /// Full invalidation drops this; a same-bucket single-item update patches
    /// the entry in place via `patchTaskIndex(with:)` instead.
    var taskIndexByID: [String: WorkTask]?
    /// Backing storage for the `dependencyPrereqsByTaskID` / `gatingPrereqsByTaskID`
    /// accessors (in ChatViewModel+Dependencies). `nil` means "invalidated —
    /// rebuild on next read". Rebuilt lazily so a burst of engine events during
    /// startup coalesces into a single rebuild at the next render instead of one
    /// full graph walk per event.
    var cachedDependencyPrereqs: [String: [WorkDependencyRow]]?
    var cachedGatingPrereqs: [String: [WorkDependencyRow]]?
    /// Backing storage for `inReviewRevisions(forParentTaskID:)` /
    /// `doneRevisions(forParentTaskID:)` (ChatViewModel+BoardHelpers). `nil`
    /// means "invalidated — rebuild on next read". Before this cache
    /// existed, both accessors re-scanned every project's tasks and every
    /// product's revisions on EVERY call, and the kanban calls both once
    /// per visible card on every render. Any broad `@Published` change on
    /// this view model re-renders the whole board, so without this cache
    /// each such change re-runs an O(total tasks) scan once per card — a
    /// measured main-thread hot leaf during hover-while-scroll jank.
    /// Rebuilt lazily, same pattern as `cachedGatingPrereqs`.
    var cachedInReviewRevisionsByParentID: [String: [WorkTask]]?
    var cachedDoneRevisionsByParentID: [String: [WorkTask]]?
    /// Backing storage for `workBoardRepoMode` (ChatViewModel+BoardHelpers).
    /// `nil` means "invalidated — rebuild on next read". `WorkBoardRepoMode.compute`
    /// scans every visible card and used to re-run on each kanban render/scroll
    /// frame as a top-of-stack main-thread leaf; same pattern as
    /// `cachedInReviewRevisionsByParentID`.
    var cachedWorkBoardRepoMode: WorkBoardRepoMode?

    /// When true, published work-input `didSet` observers skip the blanket
    /// `invalidateWorkCache()` so a caller can mutate buckets and then apply
    /// keyed invalidation itself (see `applyIncrementalTaskUpdate`).
    var suppressWorkCacheInvalidation = false

    /// Which derived work caches to drop. A single-item update only clears
    /// the subsets that item can affect; bulk / filter / edge changes still
    /// use `.all`.
    struct WorkCacheInvalidation: OptionSet {
        let rawValue: Int

        /// `cachedVisibleItems`, per-column items/sections, ambiguous-repo
        /// names, and `workBoardRepoMode`.
        static let boardLayout = WorkCacheInvalidation(rawValue: 1 << 0)
        /// O(1) id → task index (`taskIndexByID`).
        static let taskIndex = WorkCacheInvalidation(rawValue: 1 << 1)
        /// Dependency / gating prereq graphs.
        static let dependencies = WorkCacheInvalidation(rawValue: 1 << 2)
        /// In-review / done revision rollup caches.
        static let revisions = WorkCacheInvalidation(rawValue: 1 << 3)

        static let all: WorkCacheInvalidation = [
            .boardLayout, .taskIndex, .dependencies, .revisions,
        ]
    }

    /// Default entry point for published work-input changes: drop every
    /// derived cache. Prefer `invalidateWorkCache(_:)` from paths that know
    /// which subsets are affected.
    func invalidateWorkCache() {
        invalidateWorkCache(.all)
    }

    /// Drop only the selected derived caches. Used by keyed single-item
    /// updates so a status flip does not rebuild the dependency graph or
    /// the full id index when bucket membership is unchanged.
    func invalidateWorkCache(_ keys: WorkCacheInvalidation) {
        if keys.contains(.boardLayout) {
            cachedVisibleItems = nil
            cachedItemsByColumn.removeAll(keepingCapacity: true)
            cachedSectionsByColumn.removeAll(keepingCapacity: true)
            cachedAmbiguousRepoNames = nil
            cachedWorkBoardRepoMode = nil
        }
        if keys.contains(.taskIndex) {
            taskIndexByID = nil
        }
        if keys.contains(.dependencies) {
            cachedDependencyPrereqs = nil
            cachedGatingPrereqs = nil
        }
        if keys.contains(.revisions) {
            cachedInReviewRevisionsByParentID = nil
            cachedDoneRevisionsByParentID = nil
        }
    }

    /// Patch one entry of the live id index without dropping it. No-op when
    /// the index has not been built yet (lazy rebuild will pick up the new
    /// row). Call only when bucket membership is unchanged.
    func patchTaskIndex(with task: WorkTask) {
        guard taskIndexByID != nil else { return }
        taskIndexByID?[task.id] = task
    }

    /// Published work-input `didSet` hook. Full invalidate unless a caller
    /// is mid-keyed mutation under `suppressWorkCacheInvalidation`.
    func notePublishedWorkInputChanged() {
        guard !suppressWorkCacheInvalidation else { return }
        invalidateWorkCache()
    }

    /// Run `body` without the bucket `didSet` observers firing a full cache
    /// drop, so the caller can finish with keyed invalidation instead.
    func withSuppressedWorkCacheInvalidation(_ body: () -> Void) {
        let wasSuppressed = suppressWorkCacheInvalidation
        suppressWorkCacheInvalidation = true
        defer { suppressWorkCacheInvalidation = wasSuppressed }
        body()
    }

    /// Inline drag-refusal banner shown next to the source card when a
    /// drag from Blocked → Doing is rejected because the row still has
    /// unsatisfied gating prereqs (design item 11). Single-slot — the
    /// previous notice is replaced when a new refusal fires.
    @Published var dragRefusalNotice: DragRefusalNotice?

    /// A drag-to-Doing whose `EvaluateDispatchAdmission` reply is still
    /// in flight. Single-slot, like `dragRefusalNotice` — a second drag
    /// landing before the first's reply arrives simply supersedes it; the
    /// stale reply is dropped by `taskID` mismatch in the event handler.
    var pendingDragAdmissionCheck: PendingDragAdmissionCheck?

    /// Set once `EvaluateDispatchAdmission` reports an active, overridable
    /// pause and no other blocker — the confirmation dialog binds to this.
    /// `nil` means no confirmation is showing.
    @Published var pendingPauseOverrideConfirmation: PauseOverrideConfirmation?

    /// Inline confirmation banner shown on the card whose
    /// `merge_when_ready_accepted` reply just arrived (`MergeFeedbackNotice`)
    /// — for `trunk_enqueued`/`enqueued` the engine's optimistic
    /// `merge_queue_state` write routes the card into the Merging section in
    /// the same handler that emits the reply, so the banner typically shows
    /// on a Merging-section card, not a Review-lane one. If the Merging
    /// section is collapsed, the banner is not visible for those actions and
    /// the 5s auto-dismiss expires unseen — acceptable for now since the
    /// section defaults to expanded. Set and auto-dismissed from
    /// `ChatViewModel+EventHandling`.
    @Published var mergeFeedbackNotice: MergeFeedbackNotice?

    // MARK: - Optimistic kanban moves

    /// Optimistic column override for a card whose drop has been accepted
    /// in the UI but not yet confirmed by the engine. `effectiveBoardColumn`
    /// consults this before falling back to the real task status, giving an
    /// instant visual response on drop.
    var optimisticColumnByTaskID: [String: WorkBoardColumnKey] = [:]
    /// Origin column for each in-flight optimistic move. Kept until the
    /// engine's `workItemUpdated` event confirms the transition (at which
    /// point it is removed without clearing the override). If `work_error`
    /// arrives while entries remain here, the card bounces back.
    var pendingMoveOriginByTaskID: [String: WorkBoardColumnKey] = [:]

    // MARK: - Live worker state

    /// Resolve a task to its current LiveWorkerState by joining
    /// `task → execution_id → run_id`. Returns `nil` when the task
    /// has no active execution or the engine has not yet seen any
    /// hook events for the run (so the live state map is empty).
    func workerLiveState(forTaskID taskID: String) -> WorkerLiveState? {
        guard let runtime = taskRuntimesByID[taskID],
              let executionID = runtime.executionID
        else {
            return nil
        }
        return liveWorkerStates.byRunID[executionID]
    }
}

import Darwin
import Foundation

/// Single source of truth for the on-disk locations the macOS app and
/// its in-process callers use to find a running Boss engine. Centralises
/// what used to be a handful of inline `/tmp/boss-engine.{sock,pid}`
/// literals scattered across `EngineProcessController`, `ChatViewModel`,
/// and miscellaneous test scaffolding.
///
/// The production accessors (`productionSocket`, `productionPID`,
/// `productionControlToken`) refuse to run from a test bundle. Tests
/// that need engine paths must construct a `BossEnginePaths.forTest(...)`
/// instance explicitly — the type system then prevents an XCTest from
/// accidentally compiling a call against the canonical paths and
/// SIGTERM'ing a 9-hour-old engine (issue #705).
///
/// `EngineProcessController.init` and `ChatViewModel.init` both take a
/// `BossEnginePaths` instance rather than reading env-fallback strings,
/// so every code path that resolves a production location goes through
/// these accessors and is subject to the test-context check.
struct BossEnginePaths {
    /// Path of the unix-domain frontend socket the engine binds.
    let socketPath: String

    /// Path of the engine's pid file. Used as an optimisation for process
    /// identification and signalling; socket reachability is the liveness
    /// oracle.
    let pidPath: String

    /// Path of the engine-control token file. Read by the shutdown
    /// RPC caller to authenticate against the running engine.
    let controlTokenPath: String

    /// Legacy runtime locations retained for one migration window. These are
    /// nil for explicit/test profiles and present only for the normal
    /// production profile.
    let legacySocketPath: String?
    let legacyPIDPath: String?

    /// Construct a paths instance explicitly. Public so tests can use
    /// `forTest(...)` (a thin wrapper); production code should call
    /// `BossEnginePaths.production()` instead so the test-context
    /// refusal is enforced.
    init(
        socketPath: String,
        pidPath: String,
        controlTokenPath: String,
        legacySocketPath: String? = nil,
        legacyPIDPath: String? = nil
    ) {
        self.socketPath = socketPath
        self.pidPath = pidPath
        self.controlTokenPath = controlTokenPath
        self.legacySocketPath = legacySocketPath
        self.legacyPIDPath = legacyPIDPath
    }

    var socketPaths: [String] {
        [socketPath] + (legacySocketPath.map { [$0] } ?? [])
    }

    var endpointPaths: [(socketPath: String, pidPath: String)] {
        var endpoints = [(socketPath, pidPath)]
        if let legacySocketPath, let legacyPIDPath {
            endpoints.append((legacySocketPath, legacyPIDPath))
        }
        return endpoints
    }

    // MARK: - Production accessors

    /// Build the production paths instance. Refuses to run from a
    /// test bundle so an accidentally-imported XCTest cannot end up
    /// here. Tests must use `forTest(...)` instead.
    ///
    /// Each field honours its established env override
    /// (`BOSS_SOCKET_PATH`, `BOSS_ENGINE_PID_PATH`,
    /// `BOSS_ENGINE_CONTROL_TOKEN_PATH`) so existing dev workflows
    /// (alternate sockets for parallel engines, test-instance profiles)
    /// keep working unchanged.
    static func production() -> BossEnginePaths {
        let socketOverride = ProcessInfo.processInfo.environment["BOSS_SOCKET_PATH"]
        let pidOverride = ProcessInfo.processInfo.environment["BOSS_ENGINE_PID_PATH"]
        let tokenOverride = ProcessInfo.processInfo.environment["BOSS_ENGINE_CONTROL_TOKEN_PATH"]
        let socketPath = socketOverride ?? productionSocketPath()
        return BossEnginePaths(
            socketPath: socketPath,
            pidPath: pidOverride ?? socketOverride.map { derivedSiblingPath(socketPath: $0, suffix: "pid") }
                ?? productionPIDPath(),
            controlTokenPath: tokenOverride
                ?? socketOverride.map { derivedSiblingPath(socketPath: $0, suffix: "control-token") }
                ?? productionControlTokenPath(),
            legacySocketPath: socketOverride == nil ? legacyProductionSocket : nil,
            legacyPIDPath: socketOverride == nil ? legacyProductionPID : nil
        )
    }

    private static func derivedSiblingPath(socketPath: String, suffix: String) -> String {
        let url = URL(fileURLWithPath: socketPath)
        let stem = url.deletingPathExtension().lastPathComponent
        return url.deletingLastPathComponent().appendingPathComponent("\(stem).\(suffix)").path
    }

    /// Legacy production paths retained for discovery during migration.
    static let legacyProductionSocket = "/tmp/boss-engine.sock"
    static let legacyProductionPID = "/tmp/boss-engine.pid"

    /// Compatibility name used by capture validation during the legacy
    /// migration window.
    static let defaultProductionSocket = legacyProductionSocket

    /// Production socket path. Honours `BOSS_SOCKET_PATH` env override;
    /// otherwise resolves under the Boss state root.
    /// Triggers a `fatalError` in test context — see `forTest(...)`.
    static func productionSocketPath() -> String {
        refuseFromTestContext("productionSocketPath()")
        if let override = ProcessInfo.processInfo.environment["BOSS_SOCKET_PATH"] {
            return override
        }
        return URL(fileURLWithPath: productionStateRoot())
            .appendingPathComponent("engine.sock").path
    }

    /// `true` when `BOSS_SOCKET_PATH` points at a non-production socket.
    ///
    /// One signal drives three capture-instance behaviours: the toolbar
    /// badge, quiet (`.accessory` + no-activate) launch, and the
    /// per-instance `UserDefaults` suite. Mirrors engine-side
    /// `is_test_fixture_socket` — no new env var.
    ///
    /// Safe to call from tests (reads the process environment only; does
    /// not go through `productionSocketPath()`'s test-context refusal).
    static var isIsolatedInstance: Bool {
        guard let sock = ProcessInfo.processInfo.environment["BOSS_SOCKET_PATH"],
              !sock.isEmpty
        else {
            return false
        }
        let normalized = URL(fileURLWithPath: sock).standardizedFileURL.path
        let legacy = URL(fileURLWithPath: legacyProductionSocket).standardizedFileURL.path
        if normalized == legacy {
            return false
        }
        // Production-shaped Application Support paths are not isolation.
        if sock.contains("Library/Application Support/Boss") {
            return false
        }
        return true
    }

    /// Production pid-file path. Honours `BOSS_ENGINE_PID_PATH`;
    /// otherwise resolves under the Boss state root.
    /// Triggers a `fatalError` in test context.
    static func productionPIDPath() -> String {
        refuseFromTestContext("productionPIDPath()")
        if let override = ProcessInfo.processInfo.environment["BOSS_ENGINE_PID_PATH"] {
            return override
        }
        return URL(fileURLWithPath: productionStateRoot())
            .appendingPathComponent("engine.pid").path
    }

    /// Production control-token path. Honours
    /// `BOSS_ENGINE_CONTROL_TOKEN_PATH`; otherwise resolves to
    /// `~/Library/Application Support/Boss/engine-control.token`,
    /// matching the engine's `default_token_path` on the Rust side.
    /// Triggers a `fatalError` in test context.
    static func productionControlTokenPath() -> String {
        refuseFromTestContext("productionControlTokenPath()")
        if let override = ProcessInfo.processInfo.environment["BOSS_ENGINE_CONTROL_TOKEN_PATH"] {
            return override
        }
        let home = ProcessInfo.processInfo.environment["HOME"] ?? NSHomeDirectory()
        return "\(home)/Library/Application Support/Boss/engine-control.token"
    }

    private static func productionStateRoot() -> String {
        let home = ProcessInfo.processInfo.environment["HOME"] ?? NSHomeDirectory()
        return URL(fileURLWithPath: home, isDirectory: true)
            .appendingPathComponent("Library", isDirectory: true)
            .appendingPathComponent("Application Support", isDirectory: true)
            .appendingPathComponent("Boss", isDirectory: true)
            .path
    }

    // MARK: - Test construction

    /// Construct an instance with explicit per-test paths. Tests that
    /// need to exercise `EngineProcessController` or `ChatViewModel`
    /// must use this — there is no production-default fallback in test
    /// context, by design.
    static func forTest(
        socketPath: String,
        pidPath: String,
        controlTokenPath: String
    ) -> BossEnginePaths {
        BossEnginePaths(
            socketPath: socketPath,
            pidPath: pidPath,
            controlTokenPath: controlTokenPath
        )
    }

    // MARK: - Test-context detection

    /// `true` when the running process loaded `XCTest`. Mirrors the
    /// detection in `ReviewNotificationCenter.isBundleContextSafe`
    /// (`NSClassFromString("XCTestCase") != nil`). Centralised here so
    /// the engine-paths gate uses the same signal the rest of the app
    /// already trusts for "running inside a test bundle".
    static var isRunningInTestContext: Bool {
        NSClassFromString("XCTestCase") != nil
    }

    /// Fail loudly when a production accessor is called from a test
    /// bundle. The message names the accessor and points at the
    /// `forTest(...)` escape hatch so a developer triaging the crash
    /// has the exact fix in the failure text. Mirroring
    /// `ReviewNotificationCenter`'s pattern; see issue #705 for the
    /// rationale (a `bazel test` resolved a hard-coded production
    /// path and SIGTERM'd a live engine).
    private static func refuseFromTestContext(_ accessor: String) {
        if isRunningInTestContext {
            fatalError(
                """
                BossEnginePaths.\(accessor) was called from an XCTest \
                bundle. Production engine paths are unavailable in test \
                context — construct BossEnginePaths.forTest(...) \
                explicitly. See issue #705 for the design rationale.
                """
            )
        }
    }
}
protocol EngineSocketControlling: Sendable {
    func isReachable(socketPath: String, timeoutSeconds: Double) -> Bool
    func peerPID(socketPath: String, timeoutSeconds: Double) -> pid_t?
    func fingerprint(socketPath: String, timeoutSeconds: Double) -> String?
    func shutdown(socketPath: String, tokenPath: String, timeoutSeconds: Double) throws -> pid_t?
    func waitForClose(socketPath: String, timeoutSeconds: Double) -> Bool
}

extension EngineSocketControlling {
    func isReachable(socketPath: String) -> Bool {
        isReachable(socketPath: socketPath, timeoutSeconds: 1)
    }
}

struct EngineSocketControl: EngineSocketControlling {
    struct ShutdownCredential {
        let token: String
        let socketPath: String
        let pid: pid_t?
    }

    func isReachable(socketPath: String, timeoutSeconds: Double = 1.0) -> Bool {
        guard let socket = connect(socketPath: socketPath, timeoutSeconds: timeoutSeconds) else {
            return false
        }
        Darwin.close(socket)
        return true
    }

    func peerPID(socketPath: String, timeoutSeconds: Double = 1.0) -> pid_t? {
        guard let socket = connect(socketPath: socketPath, timeoutSeconds: timeoutSeconds) else {
            return nil
        }
        defer { Darwin.close(socket) }

        var pid: pid_t = 0
        var length = socklen_t(MemoryLayout<pid_t>.size)
        guard getsockopt(socket, SOL_LOCAL, LOCAL_PEERPID, &pid, &length) == 0,
              pid > 1
        else {
            return nil
        }
        return pid
    }

    func fingerprint(socketPath: String, timeoutSeconds: Double) -> String? {
        guard let payload = request(
            socketPath: socketPath,
            requestID: "version-check",
            payload: ["type": "get_engine_version"],
            timeoutSeconds: timeoutSeconds
        ), payload["type"] as? String == "engine_version_result"
        else {
            return nil
        }
        return payload["binary_fingerprint"] as? String
    }

    func readShutdownCredential(tokenPath: String) throws -> ShutdownCredential {
        let raw = try Data(contentsOf: URL(fileURLWithPath: tokenPath))
        guard let json = try JSONSerialization.jsonObject(with: raw) as? [String: Any],
              let token = json["token"] as? String,
              let socketPath = json["socket_path"] as? String
        else {
            throw failure("malformed engine-control token file: \(tokenPath)")
        }
        let pid = (json["pid"] as? NSNumber).map { pid_t($0.int32Value) }
        return ShutdownCredential(token: token, socketPath: socketPath, pid: pid)
    }

    func shutdown(socketPath: String, tokenPath: String, timeoutSeconds: Double) throws -> pid_t? {
        let credential = try readShutdownCredential(tokenPath: tokenPath)
        guard standardized(credential.socketPath) == standardized(socketPath) else {
            throw failure(
                "engine-control token names socket \(credential.socketPath), not reachable socket \(socketPath)"
            )
        }
        guard let payload = request(
            socketPath: socketPath,
            requestID: "engine-stop",
            payload: ["type": "shutdown", "token": credential.token],
            timeoutSeconds: timeoutSeconds
        ) else {
            throw failure("shutdown RPC did not return a response from \(socketPath)")
        }
        switch payload["type"] as? String {
        case "shutdown_accepted":
            return credential.pid
        case "shutdown_rejected":
            throw failure("shutdown RPC rejected: \((payload["reason"] as? String) ?? "unknown reason")")
        default:
            throw failure("shutdown RPC returned an unexpected response from \(socketPath)")
        }
    }

    func waitForClose(socketPath: String, timeoutSeconds: Double) -> Bool {
        let deadline = Date().addingTimeInterval(timeoutSeconds)
        while Date() < deadline {
            if !isReachable(socketPath: socketPath, timeoutSeconds: 0.5) {
                return true
            }
            Thread.sleep(forTimeInterval: 0.1)
        }
        return !isReachable(socketPath: socketPath, timeoutSeconds: 0.5)
    }

    private func request(
        socketPath: String,
        requestID: String,
        payload: [String: Any],
        timeoutSeconds: Double
    ) -> [String: Any]? {
        guard let socket = connect(socketPath: socketPath, timeoutSeconds: timeoutSeconds) else {
            return nil
        }
        defer { Darwin.close(socket) }

        let envelope: [String: Any] = ["request_id": requestID, "payload": payload]
        guard var body = try? JSONSerialization.data(withJSONObject: envelope) else {
            return nil
        }
        body.append(0x0A)
        guard sendAll(socket: socket, data: body) else {
            return nil
        }

        var responseBuffer = Data()
        var readBuffer = [UInt8](repeating: 0, count: 4096)
        while responseBuffer.count <= 256 * 1024 {
            let count = Darwin.recv(socket, &readBuffer, readBuffer.count, 0)
            if count <= 0 {
                return nil
            }
            responseBuffer.append(contentsOf: readBuffer[..<count])
            while let newline = responseBuffer.firstIndex(of: 0x0A) {
                let line = Data(responseBuffer[..<newline])
                responseBuffer.removeSubrange(...newline)
                guard let json = try? JSONSerialization.jsonObject(with: line) as? [String: Any],
                      json["request_id"] as? String == requestID,
                      let responsePayload = json["payload"] as? [String: Any]
                else {
                    continue
                }
                return responsePayload
            }
        }
        return nil
    }

    private func connect(socketPath: String, timeoutSeconds: Double) -> Int32? {
        let socket = Darwin.socket(AF_UNIX, SOCK_STREAM, 0)
        guard socket >= 0 else { return nil }

        var timeout = timeval(
            tv_sec: Int(timeoutSeconds),
            tv_usec: Int32((timeoutSeconds.truncatingRemainder(dividingBy: 1)) * 1_000_000)
        )
        setsockopt(socket, SOL_SOCKET, SO_RCVTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
        setsockopt(socket, SOL_SOCKET, SO_SNDTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))

        var address = sockaddr_un()
        address.sun_family = sa_family_t(AF_UNIX)
        let maximumLength = MemoryLayout.size(ofValue: address.sun_path)
        let pathLength = socketPath.lengthOfBytes(using: .utf8)
        guard pathLength < maximumLength else {
            Darwin.close(socket)
            return nil
        }
        _ = socketPath.withCString { source in
            withUnsafeMutablePointer(to: &address.sun_path) { destination in
                memcpy(UnsafeMutableRawPointer(destination), source, pathLength + 1)
            }
        }
        let result = withUnsafePointer(to: address) { pointer in
            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                Darwin.connect(socket, $0, socklen_t(MemoryLayout<sockaddr_un>.size))
            }
        }
        guard result == 0 else {
            Darwin.close(socket)
            return nil
        }
        return socket
    }

    private func sendAll(socket: Int32, data: Data) -> Bool {
        data.withUnsafeBytes { bytes in
            guard let base = bytes.baseAddress else { return false }
            var sent = 0
            while sent < bytes.count {
                let count = Darwin.send(socket, base.advanced(by: sent), bytes.count - sent, 0)
                if count <= 0 {
                    return false
                }
                sent += count
            }
            return true
        }
    }

    private func standardized(_ path: String) -> String {
        URL(fileURLWithPath: path).resolvingSymlinksInPath().standardizedFileURL.path
    }

    private func failure(_ message: String) -> NSError {
        NSError(
            domain: "Boss.EngineSocketControl",
            code: 1,
            userInfo: [NSLocalizedDescriptionKey: message]
        )
    }
}

import Foundation
import Network
import os

final class EngineClient: @unchecked Sendable {
    var onEvent: (@MainActor @Sendable (EngineEvent) -> Void)?

    private let socketPaths: [String]
    private var socketIndex = 0
    private let queue = DispatchQueue(label: "Boss.EngineClient")
    private var connection: NWConnection?
    private var buffer = Data()
    /// Byte count at the front of `buffer` already scanned for a newline
    /// with none found. `consumeLines()` resumes scanning from here instead
    /// of `buffer`'s start, so a large multi-chunk message (e.g. a ~6 MB
    /// `work_tree` reply arriving as ~94 64 KiB reads) doesn't re-scan
    /// already-scanned bytes on every chunk — that repeated full-buffer
    /// scan was O(n²) in the message size. Reset to 0 whenever a line is
    /// consumed, since the unscanned region starts over from the new front.
    private var unscannedPrefixLength = 0
    private var shouldReconnect = false
    /// Consecutive reconnect attempts since the last completed
    /// `RegisterAppSession` handshake, used to index `reconnectDelays`.
    /// Reset to 0 once `app_session_registered` arrives (and on
    /// `start()`/`stop()`) so a fresh session always begins at the
    /// shortest delay. Deliberately NOT reset on the raw socket `.ready`
    /// state — see the reset site for why.
    private var reconnectAttempt = 0
    /// Backoff schedule for `scheduleReconnect()`, indexed by
    /// `reconnectAttempt` and clamped to the last entry once exhausted —
    /// mirrors the escalating-schedule shape `boss-event`'s
    /// `DEFAULT_RETRY_DELAYS_MS` uses for the same "reconnect to the
    /// engine" problem, tuned for a long-lived session instead of a
    /// short-lived CLI invocation. Without backoff a wedged/restarting
    /// engine gets hammered with a fresh connect attempt every second.
    private static let reconnectDelays: [TimeInterval] = [0.5, 1, 2, 4, 8, 15, 30]
    /// Guards against double-scheduling: a single dropped connection can
    /// reach `scheduleReconnect()` twice (once from the state handler's
    /// terminal state, once from the receive loop's EOF/error path), and
    /// without this guard each call would consume its own `reconnectAttempt`
    /// slot and leave a stray timer at the wrong (usually shorter) delay
    /// still armed underneath the one that actually reconnects — corrupting
    /// the backoff sequence with extra, unwanted connect attempts.
    private var reconnectScheduled = false
    /// Whether the current connection attempt has ever reached `.ready`.
    /// Reset per connection attempt; used to decide whether a lost
    /// connection should advance `socketIndex` (never got through, so the
    /// next candidate is worth trying) or stay put (it worked before, so
    /// don't wander off a healthy endpoint just because it dropped).
    private var reachedReady = false

    /// Thread-safe liveness signal for `EngineProcessController`'s
    /// supervision tick: true only while this connection is `.ready`. Lets
    /// supervision reuse this long-lived connection instead of opening a
    /// fresh probe socket to the engine every tick.
    private let reachableState = OSAllocatedUnfairLock(initialState: false)
    var isReachable: Bool { reachableState.withLock { $0 } }

    /// Pending engine→UI deliveries and whether a main-actor drain is
    /// already scheduled. See [[emit]] / [[drainPendingEvents]].
    private struct EventDrainState {
        var pending: [EngineEvent] = []
        var drainScheduled = false
        /// Completed drain turns (one main-actor Task hop each). Tests
        /// assert a burst of enqueues collapses to a single turn.
        var completedDrainTurns: UInt64 = 0
    }
    private let eventDrain = OSAllocatedUnfairLock(initialState: EventDrainState())

    init(socketPath: String) {
        self.socketPaths = [socketPath]
    }

    init(socketPaths: [String]) {
        precondition(!socketPaths.isEmpty)
        self.socketPaths = socketPaths
    }

    func start() {
        shouldReconnect = true
        reconnectAttempt = 0
        reconnectScheduled = false
        socketIndex = 0
        connect()
    }

    func stop() {
        shouldReconnect = false
        reconnectAttempt = 0
        reconnectScheduled = false
        reachableState.withLock { $0 = false }
        connection?.cancel()
        connection = nil
        buffer.removeAll(keepingCapacity: false)
    }

    private func connect() {
        guard connection == nil else {
            return
        }

        let parameters = NWParameters(tls: nil, tcp: NWProtocolTCP.Options())
        let endpoint = NWEndpoint.unix(path: socketPaths[socketIndex])
        let connection = NWConnection(to: endpoint, using: parameters)
        self.connection = connection

        connection.stateUpdateHandler = { [weak self] (state: NWConnection.State) in
            guard let self else { return }
            switch state {
            case .ready:
                self.reachableState.withLock { $0 = true }
                self.reachedReady = true
                self.socketIndex = 0
                self.emit(.connected)
                self.receiveNext()
            case .waiting(let error):
                self.reachableState.withLock { $0 = false }
                self.emit(.error(message: "socket waiting: \(error.localizedDescription)"))
                self.connection = nil
                connection.cancel()
                self.advanceSocketCandidateIfNeverReady()
                self.emit(.disconnected)
                self.scheduleReconnect()
            case .failed(let error):
                self.reachableState.withLock { $0 = false }
                self.emit(.error(message: "socket failed: \(error.localizedDescription)"))
                self.connection = nil
                self.advanceSocketCandidateIfNeverReady()
                self.emit(.disconnected)
                self.scheduleReconnect()
            case .cancelled:
                self.reachableState.withLock { $0 = false }
                self.connection = nil
                self.advanceSocketCandidateIfNeverReady()
                self.emit(.disconnected)
                self.scheduleReconnect()
            default:
                break
            }
        }

        connection.start(queue: queue)
    }

    /// Only wanders to the next socket candidate when this attempt never
    /// reached `.ready` — a connection that worked before dropping should
    /// retry the same (healthy) endpoint rather than rotate away from it.
    /// See `reachedReady`.
    private func advanceSocketCandidateIfNeverReady() {
        defer { reachedReady = false }
        guard !reachedReady else { return }
        socketIndex = (socketIndex + 1) % socketPaths.count
    }


    /// Test-only spy: invoked on every outbound payload before
    /// JSON-encoding. Tests inject a recorder to assert that the
    /// chore/task create flow puts `repo_remote_url` on the wire as
    /// expected (multi-repo work modeling design Q10). Setting the
    /// hook does not bypass the real send — the socket write still
    /// runs when a connection exists, so production-path callers see
    /// no behaviour change.
    var outboundRecorder: (([String: Any]) -> Void)?

    // Not `private`: called from the `EngineClient+PaneResponses.swift`
    // extension, which needs file-scoped-`private` loosened to `internal`
    // to reach it.
    /// Returns the envelope id after a socket write. `nil` when nothing
    /// was sent (`connection == nil` or the payload failed to encode) so
    /// callers do not register a pending reply that can never arrive.
    @discardableResult
    func sendLine(_ payload: [String: Any]) -> String? {
        let envelopeRequestId = UUID().uuidString
        outboundRecorder?(payload)

        // Log outbound engine_response messages so both sides of every
        // IPC round-trip have a disk record.
        if let type = payload["type"] as? String, type == "engine_response",
           let requestId = payload["request_id"] as? String,
           let response = payload["response"] as? [String: Any],
           let kind = response["kind"] as? String {
            IpcLog.shared.log(
                requestId: requestId,
                direction: "app→engine",
                kind: kind,
                body: response
            )
        }

        guard let connection else {
            emit(.error(message:"engine connection is not established"))
            return nil
        }

        do {
            let envelope: [String: Any] = [
                "request_id": envelopeRequestId,
                "payload": payload,
            ]
            var data = try JSONSerialization.data(withJSONObject: envelope, options: [])
            data.append(0x0A)

            connection.send(content: data, completion: .contentProcessed { [weak self] error in
                guard let self else { return }
                if let error {
                    self.emit(.error(message:"socket send failed: \(error.localizedDescription)"))
                }
            })
            return envelopeRequestId
        } catch {
            emit(.error(message:"failed to encode payload: \(error.localizedDescription)"))
            return nil
        }
    }

    private func receiveNext() {
        connection?.receive(minimumIncompleteLength: 1, maximumLength: 64 * 1024) {
            [weak self] data, _, isComplete, error in
            guard let self else { return }

            if let error {
                self.emit(.error(message:"socket receive failed: \(error.localizedDescription)"))
                self.connection = nil
                self.emit(.disconnected)
                self.scheduleReconnect()
                return
            }

            if let data, !data.isEmpty {
                self.buffer.append(data)
                self.consumeLines()
            }

            if isComplete {
                self.connection = nil
                self.emit(.disconnected)
                self.scheduleReconnect()
                return
            }

            self.receiveNext()
        }
    }

    private func consumeLines() {
        while true {
            let searchStart = buffer.index(buffer.startIndex, offsetBy: unscannedPrefixLength)
            guard let newline = buffer[searchStart...].firstIndex(of: 0x0A) else {
                // No delimiter in the unscanned tail; remember how much of
                // `buffer` we've already ruled out so the next chunk's
                // arrival only scans what's new.
                unscannedPrefixLength = buffer.count
                return
            }
            let lineData = buffer[..<newline]
            buffer.removeSubrange(...newline)
            unscannedPrefixLength = 0

            guard !lineData.isEmpty else {
                continue
            }

            // Reply-received timestamp for the population-timing path: the
            // instant a complete line was pulled off the socket buffer,
            // before any JSON parse. Ends the request→reply segment and
            // starts the decode segment (which includes the envelope parse
            // below — the dominant cost for a large work_tree payload).
            // One cheap clock read per engine message; nothing else here
            // depends on it, so non-work_tree lines pay only that read.
            let lineRecvNanos = PopulationTiming.now()
            let lineByteCount = lineData.count

            guard let envelope = try? JSONSerialization.jsonObject(with: Data(lineData)) as? [String: Any],
                let payload = envelope["payload"] as? [String: Any],
                let type = payload["type"] as? String
            else {
                emit(.error(message:"received invalid JSON message from engine"))
                continue
            }
            let envelopeRequestId = envelope["request_id"] as? String

            switch type {
            case "topic_event":
                let topic = payload["topic"] as? String ?? ""
                guard let eventPayload = payload["event"] as? [String: Any],
                      let eventType = eventPayload["type"] as? String
                else {
                    break
                }
                if eventType == "work_invalidated" {
                    let productId = eventPayload["product_id"] as? String
                    let itemIds = eventPayload["item_ids"] as? [String] ?? []
                    emit(.workInvalidated(topic: topic, productId: productId, itemIds: itemIds))
                } else if eventType == "resync_required" {
                    emit(.resyncRequired)
                }
            case "products_list":
                let products = (payload["products"] as? [[String: Any]] ?? []).compactMap(parseProduct)
                emit(.productsList(products: products))
            case "projects_list":
                let productId = payload["product_id"] as? String ?? ""
                let projects = (payload["projects"] as? [[String: Any]] ?? []).compactMap(parseProject)
                emit(.projectsList(productId: productId, projects: projects))
            case "work_tree":
                guard let productPayload = payload["product"] as? [String: Any],
                      let product = parseProduct(productPayload)
                else {
                    emit(.error(message:"received invalid work tree payload from engine"))
                    break
                }
                let projects = (payload["projects"] as? [[String: Any]] ?? []).compactMap(parseProject)
                let tasks = (payload["tasks"] as? [[String: Any]] ?? []).compactMap(parseTask)
                let chores = (payload["chores"] as? [[String: Any]] ?? []).compactMap(parseTask)
                let taskRuntimes = (payload["task_runtimes"] as? [[String: Any]] ?? [])
                    .compactMap(parseTaskRuntime)
                let dependencies = (payload["dependencies"] as? [[String: Any]] ?? [])
                    .compactMap(parseWorkItemDependency)
                // Population-timing: this decode runs on the EngineClient
                // serial queue (off main). Record request→reply + decode
                // duration, payload size, and item cardinalities so timing
                // correlates with the ~1,908-item real population. The
                // decoded context is stashed FIFO per product for the
                // upcoming @MainActor apply.
                let decodeEndNanos = PopulationTiming.now()
                PopulationTiming.shared.workTreeDecoded(
                    productId: product.id,
                    lineRecvNanos: lineRecvNanos,
                    decodeEndNanos: decodeEndNanos,
                    payloadBytes: lineByteCount,
                    projects: projects.count,
                    tasks: tasks.count,
                    revisions: tasks.filter { $0.kind == "revision" }.count,
                    chores: chores.count,
                    taskRuntimes: taskRuntimes.count,
                    dependencies: dependencies.count
                )
                PopulationSignpost.signposter.emitEvent(
                    PopulationSignpost.Name.decode,
                    "product=\(product.id) items=\(tasks.count + chores.count) bytes=\(lineByteCount)"
                )
                emit(.workTree(
                    product: product,
                    projects: projects,
                    tasks: tasks,
                    chores: chores,
                    taskRuntimes: taskRuntimes,
                    dependencies: dependencies
                ))
            case "work_item_created":
                guard let itemPayload = payload["item"] as? [String: Any],
                      let item = parseWorkItem(itemPayload)
                else {
                    emit(.error(message: "received invalid work item payload from engine"))
                    break
                }
                emit(.workItemCreated(item: item))
            case "work_items_created":
                let rawItems = payload["items"] as? [[String: Any]] ?? []
                let items = rawItems.compactMap(parseWorkItem)
                if !items.isEmpty {
                    emit(.workItemsCreated(items: items))
                }
            case "work_item_updated":
                guard let itemPayload = payload["item"] as? [String: Any],
                      let item = parseWorkItem(itemPayload)
                else {
                    emit(.error(message: "received invalid work item payload from engine"))
                    break
                }
                emit(.workItemUpdated(item: item))
            case "project_tasks_reordered":
                let projectId = payload["project_id"] as? String ?? ""
                let taskIds = payload["task_ids"] as? [String] ?? []
                emit(.projectTasksReordered(projectId: projectId, taskIds: taskIds))
            case "work_item_deleted":
                let id = payload["id"] as? String ?? ""
                guard !id.isEmpty else {
                    break
                }
                emit(.workItemDeleted(id: id))
            case "work_error":
                let message = payload["message"] as? String ?? "unknown work error"
                emit(.workError(message: message, requestId: envelopeRequestId))
            case "error":
                let message = payload["message"] as? String ?? "unknown engine error"
                emit(.error(message: message))
            case "app_session_registered":
                // Only a completed handshake counts as "recovered" — resetting
                // on the raw socket `.ready` state instead would let a session
                // that connects but is immediately evicted again (e.g. a
                // trust-check rejection, or the engine tearing down a session
                // it can't register) hot-loop reconnects at the shortest delay
                // forever instead of backing off.
                reconnectAttempt = 0
                emit(.appSessionRegistered)
            case "engine_pool_config":
                let workerSlots = (payload["worker_slots"] as? NSNumber)?.intValue ?? 8
                let automationSlots = (payload["automation_slots"] as? NSNumber)?.intValue ?? 3
                let reviewSlots = (payload["review_slots"] as? NSNumber)?.intValue ?? 8
                let coordinatorModel = payload["coordinator_model"] as? String ?? "opus"
                emit(.enginePoolConfig(workerSlots: workerSlots, automationSlots: automationSlots, reviewSlots: reviewSlots, coordinatorModel: coordinatorModel))
            case "engine_request":
                guard
                    let requestId = payload["request_id"] as? String,
                    let request = payload["request"] as? [String: Any],
                    let kind = request["kind"] as? String
                else {
                    emit(.error(message:"engine_request missing required fields"))
                    break
                }
                IpcLog.shared.log(
                    requestId: requestId,
                    direction: "engine→app",
                    kind: kind,
                    body: request
                )
                switch kind {
                case "spawn_worker_pane":
                    let runId = request["run_id"] as? String ?? ""
                    let workspacePath = request["workspace_path"] as? String ?? ""
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    let initialInput = request["initial_input"] as? String ?? ""
                    let env = (request["env"] as? [[String: Any]] ?? []).compactMap {
                        item -> (String, String)? in
                        guard let k = item["key"] as? String, let v = item["value"] as? String else {
                            return nil
                        }
                        return (k, v)
                    }
                    let summary = request["summary"] as? String
                    let taskTitle = request["task_title"] as? String
                    let paneMonitorDict = request["pane_monitor"] as? [String: Any]
                    // Parse only when the engine actually sent a dict;
                    // absent/null keeps the app-side Claude default.
                    let paneMonitor: PaneMonitorSpec? = paneMonitorDict.map {
                        PaneMonitorSpec.fromWire($0)
                    }
                    let spawn = EngineSpawnRequest(
                        runId: runId,
                        workspacePath: workspacePath,
                        slotId: slotId,
                        initialInput: initialInput,
                        env: env,
                        summary: summary,
                        taskTitle: taskTitle,
                        paneMonitor: paneMonitor
                    )
                    emit(.engineRequest(requestId: requestId, request: .spawnWorkerPane(spawn)))
                case "release_worker_pane":
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    let killGrace = (request["kill_grace_seconds"] as? NSNumber)?.uint32Value ?? 0
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .releaseWorkerPane(slotId: slotId, killGraceSeconds: killGrace)
                    ))
                case "attach_worker_pane":
                    let runId = request["run_id"] as? String ?? ""
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    let sessionName = request["session_name"] as? String ?? ""
                    let tmuxSocketPath = request["tmux_socket_path"] as? String ?? ""
                    let summary = request["summary"] as? String
                    let taskTitle = request["task_title"] as? String
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .attachWorkerPane(EngineAttachRequest(
                            runId: runId,
                            slotId: slotId,
                            sessionName: sessionName,
                            tmuxSocketPath: tmuxSocketPath,
                            summary: summary,
                            taskTitle: taskTitle
                        ))
                    ))
                case "attach_coordinator_pane":
                    let sessionName = request["session_name"] as? String ?? ""
                    let spawnToken = request["spawn_token"] as? String ?? ""
                    let model = request["model"] as? String ?? ""
                    let tmuxProgram = request["tmux_program"] as? String ?? ""
                    let tmuxSocketPath = request["tmux_socket_path"] as? String ?? ""
                    let newerInstalledClaudeVersion = request["coordinator_update_available_version"] as? String
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .attachCoordinatorPane(EngineCoordinatorAttachRequest(
                            sessionName: sessionName,
                            spawnToken: spawnToken,
                            model: model,
                            tmuxProgram: tmuxProgram,
                            tmuxSocketPath: tmuxSocketPath,
                            newerInstalledClaudeVersion: newerInstalledClaudeVersion
                        ))
                    ))
                case "detach_worker_pane":
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    emit(.engineRequest(requestId: requestId, request: .detachWorkerPane(slotId: slotId)))
                case "send_to_pane":
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    let text = request["text"] as? String ?? ""
                    let expectedDriverBinary = request["expected_driver_binary"] as? String ?? ""
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .sendToPane(
                            slotId: slotId,
                            text: text,
                            expectedDriverBinary: expectedDriverBinary
                        )
                    ))
                case "focus_worker_pane":
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .focusWorkerPane(slotId: slotId)
                    ))
                case "interrupt_worker_pane":
                    let slotId = (request["slot_id"] as? NSNumber)?.intValue ?? 0
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .interruptWorkerPane(slotId: slotId)
                    ))
                case "reveal_work_item":
                    let workItemId = request["work_item_id"] as? String ?? ""
                    let productId = request["product_id"] as? String ?? ""
                    emit(.engineRequest(
                        requestId: requestId,
                        request: .revealWorkItem(workItemId: workItemId, productId: productId)
                    ))
                case "open_document":
                    let path = request["path"] as? String ?? ""
                    emit(.engineRequest(requestId: requestId, request: .openDocument(path: path)))
                case "list_hosted_panes":
                    emit(.engineRequest(requestId: requestId, request: .listHostedPanes))
                default:
                    emit(.error(message:"engine_request unknown kind: \(kind)"))
                }
            case "worker_live_states_list":
                let raw = payload["states"] as? [[String: Any]] ?? []
                let states = raw.compactMap(parseWorkerLiveState)
                emit(.workerLiveStatesList(states: states))
            case "live_status_disabled_slots_list":
                let raw = payload["slot_ids"] as? [Any] ?? []
                let slotIds = raw.compactMap { ($0 as? NSNumber)?.intValue }
                emit(.liveStatusDisabledSlotsList(slotIds: slotIds))
            case "live_status_enabled_set":
                let slotId = (payload["slot_id"] as? NSNumber)?.intValue ?? 0
                let enabled = (payload["enabled"] as? NSNumber)?.boolValue ?? false
                emit(.liveStatusEnabledSet(slotId: slotId, enabled: enabled))
            case "project_design_doc_resolved":
                guard let outputPayload = payload["output"] as? [String: Any],
                      let outputData = try? JSONSerialization.data(withJSONObject: outputPayload),
                      let output = try? JSONDecoder().decode(
                        ResolveProjectDesignDocOutput.self,
                        from: outputData
                      )
                else {
                    emit(.error(message: "received invalid project_design_doc_resolved payload"))
                    break
                }
                emit(.projectDesignDocResolved(output: output))
            case "dispatch_admission_evaluated":
                guard let admissionPayload = payload["admission"] as? [String: Any],
                      let admissionData = try? JSONSerialization.data(withJSONObject: admissionPayload),
                      let admission = try? JSONDecoder().decode(DispatchAdmission.self, from: admissionData)
                else {
                    emit(.error(message: "received invalid dispatch_admission_evaluated payload"))
                    break
                }
                emit(.dispatchAdmissionEvaluated(admission: admission))
            case "product_design_docs_list":
                guard let statePayload = payload["state"] as? [String: Any],
                      let stateData = try? JSONSerialization.data(withJSONObject: statePayload),
                      let state = try? JSONDecoder().decode(DesignDocTreeState.self, from: stateData)
                else {
                    emit(.error(message: "received invalid product_design_docs_list payload"))
                    break
                }
                emit(.productDesignDocsList(
                    productID: payload["product_id"] as? String ?? "",
                    state: state
                ))
            case "product_design_doc_content":
                guard let contentPayload = payload["content"] as? [String: Any],
                      let contentData = try? JSONSerialization.data(withJSONObject: contentPayload),
                      let content = try? JSONDecoder().decode(DesignDocContent.self, from: contentData)
                else {
                    emit(.error(message: "received invalid product_design_doc_content payload"))
                    break
                }
                emit(.productDesignDocContent(
                    ref: DesignDocRef(
                        repoRemoteURL: payload["repo_remote_url"] as? String ?? "",
                        path: payload["path"] as? String ?? "",
                        gitRef: payload["git_ref"] as? String ?? ""
                    ),
                    content: content
                ))
            case "conflict_resolutions_list":
                let raw = payload["attempts"] as? [[String: Any]] ?? []
                let attempts = raw.compactMap(parseConflictResolution)
                emit(.conflictResolutionsList(attempts: attempts))
            case "ci_remediations_list":
                let raw = payload["attempts"] as? [[String: Any]] ?? []
                let attempts = raw.compactMap(parseCiRemediation)
                emit(.ciRemediationsList(attempts: attempts))
            case "engine_attempts_list":
                let rawAttempts = payload["attempts"] as? [[String: Any]] ?? []
                let rawBackgroundWork = payload["background_work"] as? [[String: Any]] ?? []
                emit(.engineAttemptsList(
                    attempts: rawAttempts.compactMap(parseEngineAttemptListEntry),
                    backgroundWork: rawBackgroundWork.compactMap(parseBackgroundWorkItem),
                    requestId: envelopeRequestId
                ))
            case "conflict_resolution":
                guard let raw = payload["attempt"] as? [String: Any],
                      let attempt = parseConflictResolution(raw)
                else {
                    emit(.error(message: "received invalid conflict_resolution payload"))
                    break
                }
                emit(.conflictResolution(attempt: attempt))
            case "ci_remediation":
                guard let raw = payload["attempt"] as? [String: Any],
                      let attempt = parseCiRemediation(raw)
                else {
                    emit(.error(message: "received invalid ci_remediation payload"))
                    break
                }
                emit(.ciRemediation(attempt: attempt))
            case "conflict_resolution_started":
                emit(.conflictResolutionStarted(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? ""
                ))
            case "conflict_resolution_succeeded":
                emit(.conflictResolutionSucceeded(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? ""
                ))
            case "conflict_resolution_failed":
                emit(.conflictResolutionFailed(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? "",
                    failureReason: payload["failure_reason"] as? String ?? ""
                ))
            case "conflict_resolution_abandoned":
                emit(.conflictResolutionAbandoned(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? "",
                    failureReason: payload["failure_reason"] as? String ?? ""
                ))
            case "ci_remediation_started":
                emit(.ciRemediationStarted(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? "",
                    attemptKind: payload["attempt_kind"] as? String ?? ""
                ))
            case "ci_remediation_succeeded":
                emit(.ciRemediationSucceeded(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? ""
                ))
            case "ci_failure_cleared":
                emit(.ciFailureCleared(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? ""
                ))
            case "ci_remediation_failed":
                emit(.ciRemediationFailed(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? "",
                    failureReason: payload["failure_reason"] as? String ?? ""
                ))
            case "ci_remediation_abandoned":
                emit(.ciRemediationAbandoned(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    attemptID: payload["attempt_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? "",
                    failureReason: payload["failure_reason"] as? String ?? ""
                ))
            case "ci_remediation_exhausted":
                emit(.ciRemediationExhausted(
                    productID: payload["product_id"] as? String ?? "",
                    workItemID: payload["work_item_id"] as? String ?? "",
                    prURL: payload["pr_url"] as? String ?? "",
                    attemptsUsed: (payload["attempts_used"] as? NSNumber)?.intValue ?? 0,
                    budget: (payload["budget"] as? NSNumber)?.intValue ?? 0
                ))
            case "feature_flags_list":
                let raw = payload["flags"] as? [[String: Any]] ?? []
                let flags = raw.compactMap(parseFeatureFlag)
                emit(.featureFlagsList(flags: flags))
            case "feature_flag_set":
                let name = payload["name"] as? String ?? ""
                let enabled = (payload["enabled"] as? NSNumber)?.boolValue ?? false
                if !name.isEmpty {
                    emit(.featureFlagSet(name: name, enabled: enabled))
                }
            case "engine_health_result":
                let report = payload["report"] as? [String: Any] ?? [:]
                let apiKeyPresent = (report["anthropic_api_key_present"] as? NSNumber)?.boolValue ?? false
                let rawIssues = report["issues"] as? [[String: Any]] ?? []
                let issues = rawIssues.compactMap(parseEngineHealthIssue)
                emit(.engineHealthResult(apiKeyPresent: apiKeyPresent, issues: issues))
            case "driver_traffic_split_result":
                let raw = payload["split"] as? [String: Any] ?? [:]
                // A share the engine did not send would make the decoded
                // split fail its sum-to-100 invariant, so fall back to the
                // engine default wholesale rather than to a partly-decoded
                // split the UI would then treat as real.
                let decoded = DriverTrafficSplit(
                    grok: (raw["grok"] as? NSNumber)?.intValue ?? 0,
                    claude: (raw["claude"] as? NSNumber)?.intValue ?? 0,
                    codex: (raw["codex"] as? NSNumber)?.intValue ?? 0
                )
                emit(.driverTrafficSplitResult(split: decoded.isValid ? decoded : .engineDefault))
            case "driver_quota_usage_result":
                let raw = payload["snapshot"] as? [String: Any] ?? [:]
                emit(.driverQuotaUsageResult(snapshot: DriverQuotaSnapshot.decode(raw)))
            case "trunk_status":
                let configured = (payload["configured"] as? NSNumber)?.boolValue ?? false
                let source = payload["source"] as? String
                let queueCheck = (payload["queue_check"] as? [String: Any]).flatMap(parseTrunkQueueCheck)
                let note = payload["note"] as? String
                emit(.trunkStatus(configured: configured, source: source, queueCheck: queueCheck, note: note))
            case "settings_list":
                let raw = payload["settings"] as? [[String: Any]] ?? []
                let settings = raw.compactMap(parseEngineSetting)
                emit(.settingsList(settings: settings))
            case "setting_set":
                let key = payload["key"] as? String ?? ""
                let enabled = (payload["enabled"] as? NSNumber)?.boolValue ?? false
                if !key.isEmpty {
                    emit(.settingSet(key: key, enabled: enabled))
                }
            case "hosts_list":
                let raw = payload["hosts"] as? [[String: Any]] ?? []
                let hosts = raw.compactMap(parseEngineHost)
                emit(.hostsList(hosts: hosts))
            case "host_result":
                if let raw = payload["host"] as? [String: Any],
                   let host = parseEngineHost(raw) {
                    emit(.hostResult(host: host))
                }
            case "host_updated":
                if let raw = payload["host"] as? [String: Any],
                   let host = parseEngineHost(raw) {
                    emit(.hostUpdated(host: host))
                }
            case "host_removed":
                let hostId = payload["id"] as? String ?? ""
                if !hostId.isEmpty {
                    emit(.hostRemoved(id: hostId))
                }
            case "metrics_list_live_result":
                let raw = payload["entries"] as? [[String: Any]] ?? []
                let entries = raw.compactMap(parseEngineMetric)
                emit(.metricsListLiveResult(entries: entries))
            case "attention_items_for_work_item_list":
                let workItemID = payload["work_item_id"] as? String ?? ""
